// talkTo/renderNpc/serviceNpc/showModal/closeModal/restart/toggleMapForDeath and the pause
// menu / modal-content / modal-primary / modal-secondary / modal-shade bindings moved
// verbatim out of main.js (M8). Free identifiers: $ (./dom.js, throughout). npcDialogue/
// questSummary (./campaign.js, renderNpc/showModal). npcPortraitFor (./npc-portraits.js,
// renderNpc). renderDialogue/handleDialogueKey (./dialogue.js, renderNpc/the modal-shade
// keydown binding). pauseMenuMarkup/bindPauseMenu (./pause-menu.js, showModal/the pause menu
// binding). updateMenuNavigation (./menu-chrome.js, showModal). mapFor/CHECKPOINTS
// (./regions.js, showModal). saveGameSettings/applyGameVisuals (./game-settings.js, the pause
// menu's onSetting). distance (./combat.js, talkTo). document (global, showModal/the
// modal-shade keydown binding). ctx.life/ctx.player/ctx.state/ctx.currentNpc/ctx.prefabs/
// ctx.mainMenuOpen/ctx.ready/ctx.network/ctx.mapExpanded/ctx.modalKind/ctx.previousFocus/
// ctx.paused/ctx.audio/ctx.backgrounded/ctx.activeJourney/ctx.gameSettings/ctx.autosave/
// ctx.sessionMode/ctx.journeyLeaving/ctx.journeyConflict/ctx.rosterPicker/ctx.renderer/
// ctx.scene/ctx.shake (already-declared ctx data fields). ctx.awaken (M7's createGameAudio).
// ctx.releaseInput (M5's bindInput). ctx.syncAudioState (M7's createGameAudio, closeModal
// already called it as ctx.syncAudioState). ctx.inventoryPreviews/ctx.renderInventory/
// ctx.equipOwnedItem/ctx.consumePouchItem (M8's createInventoryUi). ctx.updateSaveStatus/
// ctx.saveAndExit (main.js functions this task adds to ctx, since the pause menu and the
// death-modal save-and-exit button reach across the module boundary). ctx.resumeFromMainMenu/
// ctx.openRoster/ctx.canChangeCharacter (session lifecycle, read lazily). talkTo calls showModal directly; showModal
// calls renderNpc directly; the pause-menu/modal-primary/modal-content bindings call
// closeModal/restart/serviceNpc directly -- all stay in this closure, same as awaken calling
// syncAudioState directly in game-audio.js.
import {$} from './dom.js';
import {npcDialogue,questSummary} from './campaign.js';
import {npcPortraitFor} from './npc-portraits.js';
import {renderDialogue,handleDialogueKey} from './dialogue.js';
import {pauseMenuMarkup,bindPauseMenu} from './pause-menu.js';
import {updateMenuNavigation} from './menu-chrome.js';
import {mapFor,CHECKPOINTS} from './regions.js';
import {saveGameSettings,applyGameVisuals} from './game-settings.js';
import {distance} from './combat.js';
export function createModals(ctx,deps={}){
 function talkTo(id){ctx.awaken();const npc=ctx.life.visibleNpcs().find(n=>n.id===id);if(!npc||distance(ctx.player.position,npc.model.position)>2.8)return false;if(!ctx.state.talkedTo.includes(id))ctx.state.talkedTo.push(id);ctx.currentNpc=id;showModal('npc');return true;}
 function renderNpc(){const data=npcDialogue(ctx.state,ctx.currentNpc);if(!data)return;$('modal-eyebrow').textContent=data.role.toUpperCase();$('modal-title').textContent=data.name;const portrait=npcPortraitFor(ctx.prefabs[data.model]),figure=$('dialogue-portrait'),image=figure.querySelector('img');figure.hidden=!portrait;figure.closest('.modal').classList.toggle('has-npc-portrait',!!portrait);if(portrait){if(image.getAttribute('src')!==portrait)image.src=portrait;image.alt=data.name;}renderDialogue($('modal-content'),data,ctx.state);}
 function serviceNpc(action){if(ctx.modalKind!=='npc'||!ctx.currentNpc)return{ok:false,reason:'Speak to a villager first.'};return{ok:ctx.network.send('service',{npcId:ctx.currentNpc,action})};}
 function showModal(kind){if(ctx.mainMenuOpen&&kind!=='death')return;if(!ctx.ready||!ctx.network?.connected||ctx.mapExpanded||ctx.state.ended&&kind!=='death')return;ctx.inventoryPreviews.hide();if(kind!=='death'&&kind!=='victory')ctx.audio.play('ui-open',.55);if(!ctx.modalKind)ctx.previousFocus=document.activeElement;ctx.modalKind=kind;ctx.paused=true;ctx.releaseInput();ctx.audio.pause(true,ctx.backgrounded);$('modal-shade').hidden=false;$('modal-secondary').hidden=true;$('inventory-purse').hidden=kind!=='inventory';$('inventory-controls').hidden=kind!=='inventory';document.querySelector('.modal').classList.toggle('inventory-modal',kind==='inventory');document.querySelector('.modal').classList.toggle('pause-modal',kind==='pause');document.querySelector('.modal').classList.toggle('npc-modal',kind==='npc');$('modal-shade').classList.toggle('npc-conversation',kind==='npc');$('modal-primary').hidden=kind==='npc'||kind==='pause';$('dialogue-portrait').hidden=true;document.querySelector('.modal').classList.remove('has-npc-portrait');$('modal-eyebrow').textContent=kind==='victory'?'THE BELLKEEPER DEFEATED':kind==='death'?'THE VEIL TAKES ANOTHER':'THE ASHEN VIGIL';const title=$('modal-title'),content=$('modal-content'),primary=$('modal-primary');
  const modal=content.closest('.modal');modal.dataset.menuKind=kind;
  updateMenuNavigation($('modal-navigation'),kind,{disabled:kind==='death',canChangeCharacter:ctx.canChangeCharacter()});
  $('modal-subtitle').textContent=({inventory:'What you carry into the dark.',pause:ctx.sessionMode==='single-player'?'A moment before the road calls.':'The shared world keeps moving. Rest in Ashwick to stay safe.',journal:'Every step leaves a story.',help:'Know your calling. Master the vigil.',npc:'A familiar face along the road.',death:'The vigil is not over.',victory:'A new dawn for Hallowmere.'})[kind]||'';
  modal.scrollTop=0;modal.querySelector('.chronicle-stage').scrollTop=0;
  if(kind==='pause'){title.textContent=ctx.sessionMode==='single-player'?'Game paused':'Game menu';content.innerHTML=pauseMenuMarkup(ctx.gameSettings,{journey:!!ctx.activeJourney,canChangeCharacter:ctx.canChangeCharacter()});if(ctx.activeJourney){ctx.autosave?.changed();ctx.autosave?.flush().catch(()=>{});ctx.updateSaveStatus();}}
  if(kind==='help'){title.textContent='Game controls';content.innerHTML='<div class="chronicle-controls"><div class="controls-table"><div><span>Move / attack a creature</span><kbd>WASD / LEFT CLICK</kbd></div><div><span>Stand and attack</span><kbd>SHIFT + CLICK</kbd></div><div><span>Secondary class skill</span><kbd>RIGHT CLICK</kbd></div><div><span>Evade the red attack zones</span><kbd>1</kbd></div><div><span>Major class skill / healing draught</span><kbd>2 / 3</kbd></div><div><span>Interact / enter cave / rest</span><kbd>F</kbd></div><div><span>Inventory & pouch / journal / map</span><kbd>I / J / M</kbd></div></div><p>Move the mouse near a creature to highlight it, then click to attack. Hold to keep attacking that creature; release to unlock. Ranged attacks fire from where you stand. Melee attacks approach into reach; hold Shift to stand still. '+(ctx.sessionMode==='single-player'?'Press C or open the pause menu to change character.':'Press C at a sanctuary to change class.')+(ctx.activeJourney?' Autosave is always on; continuing returns you to your last checkpoint.':'')+' Activate the lantern in each region to set your return checkpoint. Watch for faint light and displaced stones to discover caves; their tunnels connect the regions as bosses fall. Use F or tap a landmark to enter passages, cleanse shrines, and open caches. Essence regenerates. Crowns are collected by walking over them; equipment and draughts glow on the ground. Forage mushrooms, moonleaf, and berries with F or a plant label. Open Inventory with I and click food in your pouch to restore health or essence. Hold Alt to reveal nearby loot and plants during combat. Ashwick and Rook’s lantern are safe places to rest. Walk through a door or tap Enter to explore a room. Tap Leave to return outside. Hallowmere’s chapel opens after the Bellkeeper falls.</p></div>';primary.textContent='Close controls';}
  if(kind==='journal'){const quest=questSummary(ctx.state);title.textContent=quest.title;content.innerHTML=`<div class="journal-copy"><section><span class="chronicle-label">THE LAST TOLL</span><p>Hallowmere’s chapel bell has rung for thirteen years. The dead now haunt the road from Ashwick, and the Bellkeeper still pulls the rope.</p><p><strong>${quest.objective}</strong><br>${quest.hint}</p></section><section class="journal-progress"><span class="chronicle-label">YOUR JOURNEY</span><p>Mourning Road: ${ctx.state.roadKills} monsters slain<br>Hallowmere: ${ctx.state.villageKills} / 12 afflicted<br>Bellkeeper: ${ctx.state.victory?'Defeated':ctx.state.bossSpawned?'Awakened':'Not yet awakened'}${Object.entries(ctx.state.regionProgress||{}).map(([id,p])=>`<br>${mapFor(id).name}: ${p.bossDefeated?'Boss defeated':p.bossSpawned?'Boss awakened':'Exploring'}`).join('')}<br>Hidden entrances discovered: ${ctx.state.discoveries?.length||0}<br>Spoils collected: ${ctx.state.lootCollected}<br>Village reward: ${ctx.state.questRewarded?'Claimed':'80 crowns from Elder Rowan'}</p></section></div>`;primary.textContent='Close journal';}
  if(kind==='npc')renderNpc();
  if(kind==='inventory'){title.textContent='Inventory';ctx.renderInventory();primary.textContent='Close inventory';}
  if(kind==='death'){title.textContent='Return to the lanterns';content.innerHTML=`<p>${ctx.sessionMode==='multiplayer'?'Your allies continue the fight.<br>':''}Return to ${CHECKPOINTS.find(c=>c.id===ctx.state.checkpointId)?.name||'Ashwick'} with your equipment intact.</p><div class="victory-stats"><div><strong>${ctx.state.kills}</strong><span>SLAIN</span></div><div><strong>${ctx.state.souls}</strong><span>SOULS</span></div></div>`;primary.textContent='Respawn at checkpoint';if(ctx.activeJourney)content.insertAdjacentHTML('beforeend','<button type="button" class="text-button" data-save-exit>Save &amp; exit</button><span class="journey-save-status" data-save-status role="status"></span>');}
  if(kind==='victory'){title.textContent='At last, silence';content.innerHTML=`<p>The Bellkeeper falls. For the first time in thirteen years, Hallowmere hears the wind.</p><div class="legendary-reward"><span>LEGENDARY WEAPON RECOVERED</span><strong>Bellkeeper’s Requiem</strong><p>+18 primary damage · Equip it in your inventory.</p></div><p>Return to Elder Rowan in Ashwick to claim the villages’ thanks.</p>`;primary.textContent='Continue playing';}if(kind==='npc')content.querySelector('.dialogue-response:not(:disabled), [data-dialogue-close]')?.focus({preventScroll:true});else if(kind==='pause')content.querySelector('[data-resume-game]').focus({preventScroll:true});else primary.focus({preventScroll:true});}
 function closeModal(){if(ctx.journeyLeaving||ctx.journeyConflict)return;if(ctx.state.ended||ctx.rosterPicker?.open)return;if(ctx.mainMenuOpen){ctx.resumeFromMainMenu();return;}ctx.inventoryPreviews.hide();ctx.audio.play('ui-close',.5);$('modal-shade').hidden=true;ctx.paused=false;ctx.syncAudioState();ctx.modalKind='';ctx.currentNpc=null;ctx.previousFocus?.focus?.({preventScroll:true});$('world').focus({preventScroll:true});}
 bindPauseMenu($('modal-content'),{
  onResume:()=>{closeModal();ctx.awaken();},
  onSaveExit:ctx.saveAndExit,
  onChangeCharacter:()=>ctx.openRoster(),
  onSetting:(key,value)=>{
   ctx.gameSettings[key]=value;saveGameSettings(ctx.gameSettings);
   if(key==='music'){ctx.audio.musicEnabled=value;ctx.audio.applyState();if(value)ctx.awaken();}
   else{applyGameVisuals(ctx.gameSettings,ctx.renderer,ctx.scene);if(key==='cameraShake')ctx.shake=0;}
  }
 });
 $('modal-content').addEventListener('click',event=>{if(event.target.closest('[data-dialogue-close]')){closeModal();ctx.awaken();return;}const food=event.target.closest('[data-consume]');if(food){const result=ctx.consumePouchItem(food.dataset.consume);if(!result.ok)ctx.toast(result.reason);return;}if(event.target.closest('[data-open-roster]')){ctx.openRoster();return;}const item=event.target.closest('[data-select-item]');if(item){const r=ctx.equipOwnedItem(item.dataset.selectItem);if(!r.ok)ctx.toast(r.reason);return;}const service=event.target.closest('[data-service]');if(service&&!service.disabled){const r=serviceNpc(service.dataset.service);if(!r.ok)ctx.toast(r.reason);}});
 $('modal-primary').onclick=()=>{if(ctx.modalKind==='death')restart();else{closeModal();ctx.awaken();}};$('modal-secondary').onclick=restart;$('modal-shade').addEventListener('keydown',e=>{if(ctx.modalKind==='npc'&&handleDialogueKey(e,$('modal-content')))return;if(e.key!=='Tab')return;const focusable=[...$('modal-shade').querySelectorAll('button:not(:disabled), input:not(:disabled), select:not(:disabled), a[href], summary')].filter(el=>el.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}});
 function restart(){if(!ctx.network?.connected)return;if(ctx.state.ended){ctx.network.send('respawn');}else{ctx.network.send(ctx.sessionMode==='single-player'?'restart':'vote',{agree:true});closeModal();}}
 function toggleMapForDeath(){ctx.mapExpanded=false;const panel=document.querySelector('.map-panel');panel.classList.remove('expanded');for(const attr of ['role','aria-modal','aria-labelledby'])panel.removeAttribute(attr);$('map-button').setAttribute('aria-label','Expand map');ctx.paused=false;}
 return {talkTo,renderNpc,serviceNpc,showModal,closeModal,restart,toggleMapForDeath};
}
